import flamegraph from './github/graphs/flamegraph'
import {observe} from '@github-ui/selector-observer'
import {getBaseFetchHeaders} from '@github-ui/fetch-headers'

async function render(graph: Element) {
  const url = graph.getAttribute('data-url')!

  const response = await fetch(url.replace(/&amp;/g, '&'), {
    headers: {
      ...getBaseFetchHeaders(),
    },
  })
  if (!response.ok) {
    return
  }

  flamegraph(await response.json())
}

observe('.flamegraph', graph => {
  render(graph)
})
